#!/usr/bin/env bash
# Universal transactional sync: Brightspace + Timetable + Courses.
#
# One command to refresh all autogenerated content in the vault, wrapped in
# a git transaction (checkpoint -> apply -> review -> confirm/rollback) as
# described in the vault note "Transaction sync system plan".
#
# Default mode syncs FROM SOURCE (prompts for Brightspace credentials and
# the MyTimetable ICS URL every run). --cached rebuilds from the local
# RAW cache instead (no network, no prompts).
#
#   ./sync.sh                                  # from source, prompts for secrets
#   ./sync.sh --cached                         # offline rebuild from cache
#   ./sync.sh --exclude 'Mentoring' --days-future 60
#   ./sync.sh --skip-timetable                 # Brightspace + Courses only
#   ./sync.sh --vault ~/Documents/OBSIDIAN/holanda   # (this is the default)
#
# Transaction coverage:
#   Timetable/ + Courses/ are git-tracked  -> checkpoint / diff / rollback via git
#   Brightspace/ is git-ignored (by policy: never commit downloaded course
#     material) -> covered by a full pre-sync backup + sha256 manifests
#     under /tmp instead. Rollback restores the backup verbatim.
set -euo pipefail

SYNC_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
BS_DIR="$SYNC_DIR/brightspace-pipeline"
TT_DIR="$SYNC_DIR/timetable-mirror"
BS_CACHE="$BS_DIR/_state/cache/raw"

VAULT="$HOME/Documents/OBSIDIAN/holanda"
CACHED=0; YES=0; NO_COMMIT=0
SKIP_BS=0; SKIP_TT=0; SKIP_CO=0; SKIP_SU=0
BS_NETID_ARG=""; BS_PASSWORD_ARG=""; TT_URL_ARG=""
DAYS_PAST=""; DAYS_FUTURE=""
EXCLUDES=()
TRACKED_GEN=(Timetable Courses)   # git-tracked generated dirs

# --- pretty output: color landmarks on terminals, plain in pipes/logs ---
if [[ -t 1 && -z "${NO_COLOR:-}" ]]; then
    C_RED=$'\e[31m'; C_GREEN=$'\e[32m'; C_YELLOW=$'\e[33m'; C_CYAN=$'\e[36m'
    C_BOLD=$'\e[1m'; C_OFF=$'\e[0m'
else
    C_RED=""; C_GREEN=""; C_YELLOW=""; C_CYAN=""; C_BOLD=""; C_OFF=""
fi
# Each helper prints a leading blank line + colored text; stage landmarks
# also append a plain copy to the run log (LOG may not exist yet: guarded).
sec()  { printf '\n%b%s%b\n' "${C_BOLD}${C_CYAN}" "$*" "${C_OFF}"; if [[ -n "${LOG:-}" ]]; then printf '\n%s\n' "$*" >> "$LOG"; fi; }
sub()  { printf '\n%b%s%b\n' "${C_BOLD}${C_YELLOW}" "$*" "${C_OFF}"; }
ok()   { printf '\n%b%s%b\n' "${C_BOLD}${C_GREEN}" "$*" "${C_OFF}"; }
warn() { printf '\n%b%b%b\n' "${C_BOLD}${C_RED}" "$*" "${C_OFF}"; }

usage() {
    cat <<'EOF'
Usage: sync.sh [options]

Universal transactional sync (Brightspace + Timetable + Courses).
Default: sync from source (prompts for credentials + ICS URL).
  --cached             rebuild from local cache, no network, no prompts
                       (Brightspace uses --stage vault; Timetable is skipped
                       unless --timetable-url is given; Courses always run)
  --vault DIR          Obsidian vault (default: ~/Documents/OBSIDIAN/holanda)
  --exclude REGEX      skip Brightspace courses by RAW code, e.g. 'CSE000'
                       (matches 'CSE000+2026+1', not display names; repeatable)
  --days-past N        Timetable window behind today (default 14)
  --days-future N      Timetable window ahead of today (default 120)
  --timetable-url URL  ICS subscription URL (else prompted, or $TIMETABLE_ICS_URL)
  --bs-netid ID        Brightspace NetID (else prompted, or $BS_NETID)
  --bs-password PW     Brightspace password (else prompted silently; prefer prompt)
  --skip-brightspace   skip the Brightspace mirror stage
  --skip-timetable     skip the Timetable mirror stage
  --skip-courses       skip the Courses hub stage
  --skip-summary       skip the dashboard refresh stage (AGENT-SUMMARY.md + Habits.md)
  --yes                accept the review default without asking
  --no-commit          apply + show review, but leave everything uncommitted
  -h, --help           this text

Secrets are exported only to the child generator processes (never logged).

Review: git diff for tracked Timetable/Courses; sha256 manifests for
git-ignored Brightspace (verbatim moves collapse to 'old -> new', changed
notes show unified diffs, whitespace/date-stamp-only churn is noise).
Destructive (prunes, Brightspace removals/moves/non-whitespace overwrites,
hand-edit hits) defaults to NO; everything else defaults to yes.
Output is color-coded on terminals (NO_COLOR=1 disables).
EOF
}

while [[ $# -gt 0 ]]; do
    case "$1" in
        --cached) CACHED=1; shift ;;
        --vault) VAULT="$2"; shift 2 ;;
        --exclude) EXCLUDES+=("$2"); shift 2 ;;
        --days-past) DAYS_PAST="$2"; shift 2 ;;
        --days-future) DAYS_FUTURE="$2"; shift 2 ;;
        --timetable-url) TT_URL_ARG="$2"; shift 2 ;;
        --bs-netid) BS_NETID_ARG="$2"; shift 2 ;;
        --bs-password) BS_PASSWORD_ARG="$2"; shift 2 ;;
        --skip-brightspace) SKIP_BS=1; shift ;;
        --skip-timetable) SKIP_TT=1; shift ;;
        --skip-courses) SKIP_CO=1; shift ;;
        --skip-summary) SKIP_SU=1; shift ;;
        --yes) YES=1; shift ;;
        --no-commit) NO_COMMIT=1; shift ;;
        -h|--help) usage; exit 0 ;;
        *) echo "error: unknown flag $1 (see --help)" >&2; exit 1 ;;
    esac
done

if [[ ! -d "$VAULT/.git" ]]; then
    echo "error: $VAULT is not a git repo — the transaction needs git" >&2
    exit 1
fi

# ---------------------------------------------------------------- secrets ---
if [[ "$CACHED" -eq 0 ]]; then
    if [[ "$SKIP_BS" -eq 0 ]]; then
        dflt="${BS_NETID_ARG:-${BS_NETID:-}}"
        if [[ -n "$dflt" && -z "$BS_NETID_ARG" ]]; then
            read -rp "Brightspace NetID [$dflt]: " ans || true
            export BS_NETID="${ans:-$dflt}"
        elif [[ -n "$BS_NETID_ARG" ]]; then
            export BS_NETID="$BS_NETID_ARG"
        else
            read -rp "Brightspace NetID: " BS_NETID || true
            export BS_NETID
        fi
        if [[ -n "$BS_PASSWORD_ARG" ]]; then
            export BS_PASSWORD="$BS_PASSWORD_ARG"
            echo "WARN: --bs-password exposes the secret in shell history and" >&2
            echo "WARN: process lists; prefer the prompt." >&2
        else
            read -rsp "Brightspace password: " BS_PASSWORD || true
            echo
            export BS_PASSWORD
        fi
    fi
    if [[ "$SKIP_TT" -eq 0 && -z "$TT_URL_ARG" && -z "${TIMETABLE_ICS_URL:-}" ]]; then
        read -rp "MyTimetable ICS URL: " TIMETABLE_ICS_URL || true
        export TIMETABLE_ICS_URL
    elif [[ -n "$TT_URL_ARG" ]]; then
        export TIMETABLE_ICS_URL="$TT_URL_ARG"
    fi
else
    # Cached: no prompts. Timetable has no offline cache (mirror.py always
    # fetches), so it is skipped unless a URL was explicitly supplied.
    if [[ "$SKIP_TT" -eq 0 && -z "$TT_URL_ARG" ]]; then
        echo "CACHED: no offline cache for Timetable — skipping it"
        echo "        (pass --timetable-url to fetch it anyway)"
        SKIP_TT=1
    elif [[ -n "$TT_URL_ARG" ]]; then
        export TIMETABLE_ICS_URL="$TT_URL_ARG"
    fi
fi

# --------------------------------------------------------------- checkpoint --
STAMP="$(date '+%Y-%m-%d %H:%M')"
TAG="pre-sync-$(date '+%Y%m%d-%H%M%S')"
if [[ -n "$(git -C "$VAULT" status --porcelain)" ]]; then
    echo "CHECKPOINT: working tree dirty — committing everything as checkpoint"
    CLEAN_BEFORE=0
else
    CLEAN_BEFORE=1
fi
git -C "$VAULT" add -A
if [[ "$CLEAN_BEFORE" -eq 1 ]]; then
    git -C "$VAULT" commit --allow-empty -qm "pre-sync checkpoint $STAMP"
else
    git -C "$VAULT" commit -qm "pre-sync checkpoint $STAMP"
fi
CHECKPOINT="$(git -C "$VAULT" rev-parse HEAD)"
git -C "$VAULT" tag "$TAG" "$CHECKPOINT"
sec "CHECKPOINT $CHECKPOINT (tag $TAG)"
# First-run edge: untracked dashboards are invisible to reset --hard,
# so remember to clean them explicitly on rollback.
SUMMARY_WAS_TRACKED=1
for f in AGENT-SUMMARY.md Habits.md; do
    git -C "$VAULT" ls-files --error-unmatch -- "$f" >/dev/null 2>&1 || SUMMARY_WAS_TRACKED=0
done

WORK="$(mktemp -d /tmp/vault-sync-XXXXXX)"
LOG="$WORK/run.log"

# Brightspace is git-ignored: snapshot it with a verbatim backup + manifests.
# Manifest lines are "<sha256>\t<relpath>", sorted by path. The hash is
# computed via stdin redirect (never parsed out of a filename-bearing line)
# because vault paths contain spaces.
bs_manifest() {  # $1 = output file
    (cd "$VAULT/Brightspace" && find . -type f -print0 | sort -z |
        while IFS= read -r -d '' f; do
            printf '%s\t%s\n' "$(sha256sum < "$f" | cut -d' ' -f1)" "$f"
        done | sort -t "$(printf '\t')" -k2,2) > "$1"
}
if [[ "$SKIP_BS" -eq 0 && -d "$VAULT/Brightspace" ]]; then
    sec "SNAPSHOT Brightspace/ backup (git-ignored, restores on rollback)"
    cp -a "$VAULT/Brightspace" "$WORK/bs-backup"
    bs_manifest "$WORK/bs-before.sums"
    # Files touched after the last successful sync OR vault build are
    # (almost certainly) hand edits inside the read-only mirror — the
    # rebuild will overwrite them. last-vault-build.txt is written by this
    # script after every successful Brightspace stage (direct per-mirror
    # runs don't update it, so the heuristic is exact only via sync.sh).
    LASTSYNC_REF=""
    for cand in "$BS_CACHE/_meta/last-sync.txt" "$BS_CACHE/_meta/last-vault-build.txt"; do
        if [[ -f "$cand" && ( -z "$LASTSYNC_REF" || "$cand" -nt "$LASTSYNC_REF" ) ]]; then
            LASTSYNC_REF="$cand"
        fi
    done
    if [[ -n "$LASTSYNC_REF" ]]; then
        (cd "$VAULT/Brightspace" && find . -type f -newer "$LASTSYNC_REF" | sort) \
            > "$WORK/bs-localmods.txt" || true
    else
        : > "$WORK/bs-localmods.txt"
    fi
else
    : > "$WORK/bs-localmods.txt"
fi

# ------------------------------------------------------------------- stages --
STAGES_RUN=()
fail=0

if [[ "$SKIP_BS" -eq 0 ]]; then
    STAGES_RUN+=("brightspace")
    BS_ARGS=(-o "$VAULT/Brightspace" --read-only --virt-folder --virt-root '! Index')
    if [[ "$CACHED" -eq 1 ]]; then
        BS_ARGS+=(--stage vault --selftest)   # stage vault skips selftest unless asked
    fi
    for rx in ${EXCLUDES[@]+"${EXCLUDES[@]}"}; do
        BS_ARGS+=(--exclude "$rx")
    done
    sec "=== STAGE brightspace ==="
    if ! python3 "$BS_DIR/main.py" "${BS_ARGS[@]}" 2>&1 | tee -a "$LOG"; then
        warn "ERROR: brightspace stage failed — rolling back" >&2
        fail=1
    elif [[ -d "$BS_CACHE/_meta" ]]; then
        date -u +%FT%TZ > "$BS_CACHE/_meta/last-vault-build.txt"
    fi
fi

if [[ "$fail" -eq 0 && "$SKIP_TT" -eq 0 ]]; then
    STAGES_RUN+=("timetable")
    TT_ARGS=(-o "$VAULT/Timetable")
    if [[ -n "$DAYS_PAST" ]]; then TT_ARGS+=(--days-past "$DAYS_PAST"); fi
    if [[ -n "$DAYS_FUTURE" ]]; then TT_ARGS+=(--days-future "$DAYS_FUTURE"); fi
    sec "=== STAGE timetable ==="
    if ! python3 "$TT_DIR/mirror.py" "${TT_ARGS[@]}" 2>&1 | tee -a "$LOG"; then
        warn "ERROR: timetable stage failed — rolling back" >&2
        fail=1
    fi
fi

if [[ "$fail" -eq 0 && "$SKIP_CO" -eq 0 ]]; then
    STAGES_RUN+=("courses")
    sec "=== STAGE courses ==="
    if ! python3 "$TT_DIR/courses.py" --vault "$VAULT" 2>&1 | tee -a "$LOG"; then
        warn "ERROR: courses stage failed — rolling back" >&2
        fail=1
    fi
fi

if [[ "$fail" -eq 0 && "$SKIP_SU" -eq 0 ]]; then
    STAGES_RUN+=("summary")
    sec "=== STAGE agent-summary ==="
    if ! python3 "$SYNC_DIR/agent-summary.py" --vault "$VAULT" 2>&1 | tee -a "$LOG"; then
        warn "WARNING: agent-summary stage failed — continuing (dashboard regenerates on access)"
    fi
fi

rollback() {
    warn "ROLLBACK to $CHECKPOINT (tag $TAG kept for inspection)"
    chmod -R u+w "$VAULT/Brightspace" "$VAULT/Timetable" "$VAULT/Courses" 2>/dev/null || true
    git -C "$VAULT" reset --hard -q "$CHECKPOINT"
    git -C "$VAULT" clean -fdq -- "${TRACKED_GEN[@]}"
    if [[ "${SUMMARY_WAS_TRACKED:-1}" -eq 0 ]]; then
        git -C "$VAULT" clean -fdq -- AGENT-SUMMARY.md Habits.md || true
    fi
    if [[ -d "$WORK/bs-backup" ]]; then
        rm -rf "$VAULT/Brightspace"
        cp -a "$WORK/bs-backup" "$VAULT/Brightspace"
        echo "Brightspace/ restored from pre-sync backup."
    fi
    echo "Rolled back. Pre-sync state is commit $CHECKPOINT / tag $TAG."
    echo "Full generator output: $LOG"
}

if [[ "$fail" -eq 1 ]]; then
    rollback
    exit 1
fi

# ------------------------------------------------------------------- review --
# Tracked dirs via git; Brightspace (ignored) via manifest comparison.
STATUS="$(git -C "$VAULT" status --porcelain -- "${TRACKED_GEN[@]}" || true)"
BS_ADDED=""; BS_REMOVED=""; BS_MODIFIED=""; BS_RENAMED=""; BS_OVERWRITE=""; BS_NOISE=0
if [[ -d "$WORK/bs-backup" ]]; then
    bs_manifest "$WORK/bs-after.sums"
    TAB="$(printf '\t')"
    BS_ADDED="$(comm -13 <(cut -f2 -d "$TAB" "$WORK/bs-before.sums") \
                         <(cut -f2 -d "$TAB" "$WORK/bs-after.sums") || true)"
    BS_REMOVED="$(comm -23 <(cut -f2 -d "$TAB" "$WORK/bs-before.sums") \
                           <(cut -f2 -d "$TAB" "$WORK/bs-after.sums") || true)"
    BS_MODIFIED="$(join -t "$TAB" -1 2 -2 2 "$WORK/bs-before.sums" \
        "$WORK/bs-after.sums" 2>/dev/null \
        | awk -F'\t' '$2 != $3 {print $1}' || true)"
    # Collapse verbatim moves: same sha256 vanished here, appeared there.
    if [[ -n "$BS_ADDED" && -n "$BS_REMOVED" ]]; then
        declare -A SHA_BEFORE=() SHA_AFTER=()
        while IFS="$TAB" read -r h p; do SHA_BEFORE["$h"]="$p"; done < "$WORK/bs-before.sums"
        while IFS="$TAB" read -r h p; do SHA_AFTER["$h"]="$p"; done < "$WORK/bs-after.sums"
        for h in "${!SHA_BEFORE[@]}"; do
            old="${SHA_BEFORE[$h]}" new="${SHA_AFTER[$h]:-}"
            if [[ -n "$new" && "$old" != "$new" ]]; then
                BS_RENAMED+="${BS_RENAMED:+$'\n'}${old} -> ${new}"
            fi
        done
        if [[ -n "$BS_RENAMED" ]]; then
            while IFS= read -r line; do
                [[ -z "$line" ]] && continue
                BS_ADDED="$(printf '%s\n' "$BS_ADDED" | grep -vxF "${line#* -> }" || true)"
                BS_REMOVED="$(printf '%s\n' "$BS_REMOVED" | grep -vxF "${line% -> *}" || true)"
            done <<< "$BS_RENAMED"
        fi
    fi
    # Unified diffs for changed text notes: full -> review.diff, capped -> stdout.
    # Classification rule: whitespace-only (or generated date-stamp only)
    # differences are noise; even one non-whitespace content change makes
    # the file an overwrite. The `Synced YYYY-MM-DD` stamp is normalized
    # away: it is machine metadata rewritten on every build, not content.
    : > "$WORK/review.diff"
    if [[ -n "$BS_MODIFIED" ]]; then
        while IFS= read -r f; do
            [[ -z "$f" ]] && continue
            rel="${f#./}"
            case "$rel" in
                *.md|*.txt|*.html|*.csv|*.s|*.py|*.c|*.h|*.java|*.vim)
                    if [[ "$(stat -c%s "$VAULT/Brightspace/$rel" 2>/dev/null || echo 0)" -lt 204800 ]]; then
                        sed 's/^Synced [0-9]\{4\}-[0-9]\{2\}-[0-9]\{2\}.*/Synced DATE/' \
                            "$WORK/bs-backup/$rel" > "$WORK/norm_a"
                        sed 's/^Synced [0-9]\{4\}-[0-9]\{2\}-[0-9]\{2\}.*/Synced DATE/' \
                            "$VAULT/Brightspace/$rel" > "$WORK/norm_b"
                        if diff -q -bB "$WORK/norm_a" "$WORK/norm_b" >/dev/null 2>&1; then
                            BS_NOISE=$((BS_NOISE + 1))
                            continue
                        fi
                        { echo "=== Brightspace/$rel"
                          diff -u --label "a/$rel (pre-sync)" --label "b/$rel (post-sync)" \
                              "$WORK/bs-backup/$rel" "$VAULT/Brightspace/$rel" || true
                        } >> "$WORK/review.diff"
                        BS_OVERWRITE+="${BS_OVERWRITE:+$'\n'}${f}"
                        continue
                    fi ;;
            esac
            s0="$(stat -c%s "$WORK/bs-backup/$rel" 2>/dev/null || echo ?)"
            s1="$(stat -c%s "$VAULT/Brightspace/$rel" 2>/dev/null || echo ?)"
            echo "* Brightspace/$rel (binary/large: $s0 -> $s1 bytes)" >> "$WORK/review.diff"
            BS_OVERWRITE+="${BS_OVERWRITE:+$'\n'}${f}"
        done <<< "$BS_MODIFIED"
    fi
fi

if [[ -z "$STATUS" && -z "$BS_ADDED" && -z "$BS_REMOVED" && -z "$BS_OVERWRITE" && -z "$BS_RENAMED" ]]; then
    ok "IN SYNC — generators ran (${STAGES_RUN[*]:-none}), nothing changed"
    if [[ "$CLEAN_BEFORE" -eq 1 ]]; then
        git -C "$VAULT" reset --quiet HEAD~1   # drop the empty checkpoint
        git -C "$VAULT" tag -d "$TAG" >/dev/null
    fi
    echo "Full generator output: $LOG"
    exit 0
fi

# Print at most $1 lines of $2, with a "(+N more)" tail.
caplist() {
    local max="$1" text="$2" n
    n="$(printf '%s\n' "$text" | grep -c . || true)"
    printf '%s\n' "$text" | head -"$max"
    if [[ "$n" -gt "$max" ]]; then echo "(+ $((n - max)) more)"; fi
}

sub "---------------- REVIEW ----------------"
if [[ -n "$STATUS" ]]; then
    sub "--- Timetable/ Courses/ (git) ---"
    git -C "$VAULT" diff --stat -- "${TRACKED_GEN[@]}" || true
    echo "--- name-status ---"
    echo "$STATUS"
fi
if [[ -d "$WORK/bs-backup" ]]; then
    nA="$(printf '%s\n' "$BS_ADDED" | grep -c . || true)"
    nR="$(printf '%s\n' "$BS_REMOVED" | grep -c . || true)"
    nM="$(printf '%s\n' "$BS_OVERWRITE" | grep -c . || true)"
    nV="$(printf '%s\n' "$BS_RENAMED" | grep -c . || true)"
    sub "--- Brightspace/ ($(wc -l < "$WORK/bs-after.sums") files: $nA added, $nR removed, $nM content-changed, $nV moved verbatim, $BS_NOISE whitespace/date-only) ---"
    [[ -n "$BS_RENAMED" ]] && { echo "[moved verbatim: old -> new]"; caplist 20 "$BS_RENAMED"; }
    [[ -n "$BS_ADDED" ]] && { echo "[added]"; caplist 20 "$BS_ADDED"; }
    [[ -n "$BS_REMOVED" ]] && { echo "[removed]"; caplist 20 "$BS_REMOVED"; }
    if [[ -n "$BS_OVERWRITE" ]]; then
        echo "[content-changed: unified diff vs pre-sync backup]"
        grep -E '^===|^[+-][^+-]' "$WORK/review.diff" | head -100 || true
        echo "(full per-file diff: $WORK/review.diff)"
    fi
fi
# Agent dashboard: derived file, shown informationally, never destructive.
SUMMARY_STATUS="$(git -C "$VAULT" status --porcelain -- AGENT-SUMMARY.md Habits.md || true)"
if [[ -n "$SUMMARY_STATUS" ]]; then
    sub "--- Dashboards (generated) ---"
    git -C "$VAULT" diff --stat -- AGENT-SUMMARY.md Habits.md || true
    echo "$SUMMARY_STATUS"
fi

# Destructive = pruned files in tracked dirs, removed / verbatim-moved /
# content-changed (non-whitespace) files in the wipe-rebuilt Brightspace
# mirror, or any changed file you hand-edited. Pure additions and
# whitespace/date-only churn are safe.
DELETED_TC="$(echo "$STATUS" | grep -E '^D |^ D' || true)"
DESTRUCTIVE=""
[[ -n "$DELETED_TC" ]] && DESTRUCTIVE="$DELETED_TC"
[[ -n "$BS_REMOVED$BS_OVERWRITE$BS_RENAMED" ]] && \
    DESTRUCTIVE="${DESTRUCTIVE}${DESTRUCTIVE:+$'\n'}${BS_REMOVED}${BS_OVERWRITE:+$'\n'}${BS_OVERWRITE}${BS_RENAMED:+$'\n'}${BS_RENAMED}"

if [[ -s "$WORK/bs-localmods.txt" && -n "$BS_REMOVED$BS_OVERWRITE$BS_RENAMED" ]]; then
    warn "WARNING: these Brightspace files were hand-edited after the last\nsync and the mirror just overwrote them (verbatim copy kept only\nin the rollback backup $WORK/bs-backup):"
    comm -12 <(sort "$WORK/bs-localmods.txt") \
             <(printf '%s\n%s\n%s' "$BS_REMOVED" "$BS_OVERWRITE" "$BS_RENAMED" | sort -u) || true
fi
if [[ -n "$DELETED_TC" ]]; then
    warn "WARNING: pruned (deleted) tracked files:"
    echo "$DELETED_TC"
fi
echo "Full generator output: $LOG"

if [[ "$NO_COMMIT" -eq 1 ]]; then
    echo "NO-COMMIT: changes applied, checkpoint $CHECKPOINT / tag $TAG kept."
    echo "Commit with: git -C \"$VAULT\" add -A && git commit"
    echo "Or roll back with: git -C \"$VAULT\" reset --hard $CHECKPOINT"
    echo "(Brightspace backup: $WORK/bs-backup)"
    exit 0
fi

# ------------------------------------------------------------------ confirm --
if [[ -n "$DESTRUCTIVE" ]]; then
    warn "DESTRUCTIVE changes detected (prunes and/or Brightspace overwrites).\nDefault is NO — an explicit 'y' is required."
    if [[ "$YES" -eq 1 ]]; then ans="n"; else read -rp "Commit these changes? [y/N] " ans || true; fi
    if [[ "$ans" == [Yy]* ]]; then DECISION=1; else DECISION=0; fi
else
    ok "Safe updates only (new files / whitespace or date-stamp only / Timetable-Courses edits)."
    if [[ "$YES" -eq 1 ]]; then ans="y"; else read -rp "Commit these changes? [Y/n] " ans || true; fi
    if [[ "$ans" == [Nn]* ]]; then DECISION=0; else DECISION=1; fi
fi

if [[ "$DECISION" -eq 1 ]]; then
    git -C "$VAULT" add -A
    git -C "$VAULT" commit -qm "sync: ${STAGES_RUN[*]} $STAMP"
    ok "COMMITTED $(git -C "$VAULT" rev-parse --short HEAD) (checkpoint tag $TAG kept)"
else
    rollback
fi
